//@ts-ignore
const useLogging = (ENVIRONMENT == "development");


// NOTE: Default ruleIdBase value matches TSS_HEURISTIC_SCAM_BASE_ID from app-consts.js
//       Cannot import due to function serialization
// Rule ID offsets (see app-consts.js for named constants):
//   +4: TSS_RULE_PRINT_LOOP
//   +5: TSS_RULE_PUSH_STATE
//   +6: TSS_RULE_CREATE_OBJECT_URL
//   +7: TSS_RULE_EXTENSION_INSTALL
//   +8: TSS_RULE_NOTIFICATION_LOOP
//   +9: TSS_RULE_REPLACE_STATE
export const SetTss = (nonce, isRepeatedFunc, funcCtx, ruleIdBase = 10000) => {

    useLogging && console.debug(`${funcCtx} TSS: hosted page injected`);
    useLogging && console.debug(`${funcCtx} MBTSS: Nonce: `, nonce);

    // hook functions
    let detected = false;
    let excluded = false;
    let lastHistoryData = {};
    let lastPrintData = {};
    let lastCreateURLData = {};
    let lastNotificationData = {};

    function setHook({object, f, subtype, ruleId, detectFunc, proxy = passthru, isBrowserlocker = true}) {
        let originalFunc = object[f];
        object[f] = function() {
            if (detected && !excluded && isBrowserlocker) {
                throw new Error('Breaking Browser Locker Behavior detected'); // Forces a failure of the original Function
            }
            let parameters = [].slice.call(arguments);
            if (!excluded && detectFunc(parameters)) {
                detected = true;
            }
            if (detected && !excluded) {
                notify(subtype, ruleId, parameters);
            }
            if (detected && !excluded && isBrowserlocker) {
                throw new Error('Breaking Browser Locker Behavior detected'); // Forces a failure of the original Function
            }
            return proxy(originalFunc, this, parameters);
        };
    }

    function notify(subtype, ruleId, parameters) {
        window.top.postMessage(JSON.parse(JSON.stringify({type: 'scam', subtype, ruleId, parameters, nonce})), window.location.origin);
    }

    function passthru( originalFunc, object, parameters ) {
        return originalFunc.apply( object, parameters );
    }


    function isRepeated(data, interval, threshold) {
        return isRepeatedFunc(data, interval, threshold);
    }

    function onPrint(_parameters) {
        useLogging && console.debug("TSS: caught print");
        return isRepeated(lastPrintData, 10000, 3);
    }

    function onHistoryPush(parameters) {
        useLogging && console.debug("TSS: Counted history being pushed");
        return onHistory(parameters);
    }

    function onHistoryReplace(parameters) {
        useLogging && console.debug("TSS: Counted history being replaced");
        return onHistory(parameters);
    }

    function onHistory( _parameters ) {
        useLogging && console.debug( "TSS: Caught history" );
        // detect if >= 500 repeated history modifications within 1 second
        return isRepeated( lastHistoryData, 1000, 500 );
    }

    function onWebstore( _parameters ) {
        useLogging && console.debug( "TSS: Caught webstore install" );
        return true;
    }

    function onCreateURL( _parameters ) {
        useLogging && console.debug( "TSS: Caught create URL" );
        // detect if >= 500 repeated URL creations within 1 second
        return isRepeated( lastCreateURLData, 1000, 500 );
    }

    // eslint-disable-next-line no-unused-vars
    function onInstallXPI( _parameters ) {
        useLogging && console.debug( "TSS: Caught install XPI" );
        return true;
    }

    function onNotification( _parameters ) {
        useLogging && console.debug( "TSS: Caught notification permission request" );
        return isRepeated( lastNotificationData, 5000, 2 );
    }

    // set hooks
    setHook({object: window, f: "print", subtype: "printLoop", ruleId: ruleIdBase + 4, detectFunc: onPrint});
    setHook({
        object: window.history, f: "pushState", subtype: "historyLoop",
        ruleId: ruleIdBase + 5, detectFunc: onHistoryPush
    });
    window.setTimeout(function() {
        setHook({
            object: window.history, f: "replaceState", subtype: "historyLoop",
            ruleId: ruleIdBase + 9, detectFunc: onHistoryReplace
        });
    }, 2000);

    setHook({
        object: URL, f: "createObjectURL", subtype: "createURLLoop",
        ruleId: ruleIdBase + 6, detectFunc: onCreateURL
    });

    if (window.chrome && window.chrome.webstore) {
        setHook({
            // eslint-disable-next-line no-undef
            object: chrome.webstore,
            f: "install",
            subtype: "extensionInstall",
            ruleId: ruleIdBase + 7,
            detectFunc: onWebstore,
            isBrowserlocker: false
        });
    }

    if (window.Notification) {
        setHook({
            object: window.Notification,
            f: "requestPermission",
            subtype: "notificationLoop",
            ruleId: ruleIdBase + 8,
            detectFunc: onNotification,
            isBrowserlocker: false
        });
    }

    // listen for exclusions notifications
    window.addEventListener( "message",
        function( event ) {
            if ( event.source === window && event.origin === window.location.origin && event.data.nonce === nonce ) {
                if ( event.data.type === "exclude" ) {
                    excluded = true;
                }
            }
        }, false
    );
};
